<section class="erp-card"><h2>صورت‌های مالی و مقایسه دوره‌ها</h2><form method="get" class="erp-filter erp-no-print"><input type="hidden" name="page_id" value="<?php echo (int)get_option('agah_erp_page_id'); ?>"><input type="hidden" name="c" value="<?php echo $cid; ?>"><input type="hidden" name="p" value="financials"><?php foreach(['from'=>['از تاریخ',Jalali::format($from,false)],'to'=>['تا تاریخ',Jalali::format($to,false)],'compare_from'=>['مقایسه از',$compareFrom],'compare_to'=>['مقایسه تا',$compareTo]] as $key=>$meta): ?><label><?php echo esc_html($meta[0]); ?><input name="<?php echo esc_attr($key); ?>" value="<?php echo esc_attr($meta[1]); ?>" data-jalali></label><?php endforeach; ?><button type="submit" class="btn btn-outline">محاسبه</button></form><?php FinanceController::exportLink($cid,'statements'); ?><button type="button" class="btn btn-outline erp-no-print" data-print>چاپ / PDF</button></section>
<?php foreach(['profit'=>'صورت سود و زیان','balance'=>'ترازنامه','cashflow'=>'صورت جریان وجوه نقد — غیرمستقیم'] as $section=>$title): ?><section class="erp-card"><h3><?php echo esc_html($title); ?></h3><?php if(in_array($section,['balance','cashflow'],true)): ?><p class="<?php echo $data[$section]['difference']?'erp-err':'erp-ok'; ?>" data-finance-balance="<?php echo esc_attr($section); ?>"><?php echo esc_html(($data[$section]['difference']?'مغایرت: ':'متوازن؛ اختلاف: ').Money::fmt($data[$section]['difference'],Ctx::unit())); ?></p><?php endif; ?><div class="erp-scroll"><table class="erp-table"><thead><tr><th>عنوان</th><th>دوره انتخابی</th><?php if($other): ?><th>دوره مقایسه</th><th>تغییر</th><?php endif; ?></tr></thead><tbody><?php foreach($labels[$section] as $key=>$label): ?><tr><td><?php echo esc_html($label); ?></td><td><?php echo esc_html(Money::fmt($data[$section][$key],Ctx::unit())); ?></td><?php if($other): ?><td><?php echo esc_html(Money::fmt($other[$section][$key],Ctx::unit())); ?></td><td><?php echo esc_html(Money::fmt(Money::add($data[$section][$key],-$other[$section][$key]),Ctx::unit())); ?></td><?php endif; ?></tr><?php endforeach; ?></tbody></table></div><?php if($section==='cashflow'): ?><p>طبقه‌بندی بر پایهٔ طبقه حساب است؛ معاملات سرمایه‌ای کاملاً غیرنقدی از جریان کنار گذاشته می‌شوند. اسناد نقدی با چند نوع فعالیت به بازبینی حسابدار نیاز دارند: <?php echo esc_html(Money::toFa($data['cashflow']['review_count'])); ?>. این خروجی جایگزین تأیید حسابدار رسمی نیست.</p><?php endif; ?></section><?php endforeach; ?>
<section class="erp-card"><h3>جزئیات حساب‌های ترازنامه</h3><div class="erp-scroll"><table class="erp-table"><thead><tr><th>کد</th><th>نام</th><th>مانده بدهکار / (بستانکار)</th></tr></thead><tbody><?php foreach($data['balance']['rows'] as $r)if(!in_array($r['stmt_class'],FinancialService::TEMP,true)): ?><tr><td><?php echo esc_html($r['code']); ?></td><td><?php echo esc_html($r['name']); ?></td><td><?php echo esc_html(Money::fmt($r['balance'],Ctx::unit())); ?></td></tr><?php endif; ?></tbody></table></div></section>
